-- DB: qnfo-audit
-- Rollback: DELETE FROM control_alternate_probes WHERE control = 'plain-article-gate' AND last_run_at IS NULL; DELETE FROM control_registry WHERE control = 'plain-article-gate'; DELETE FROM remediation_contracts WHERE class IN ('fm-quick-read-extract-not-plain', 'fm-plain-article-coverage-stalls'); DELETE FROM failure_modes WHERE fm_key IN ('quick-read-extract-not-plain', 'plain-article-coverage-stalls'); DELETE FROM output_quality_measures WHERE metric IN ('plain_article_coverage_pct', 'ask_plain_share_7d'); DELETE FROM analytics_metric_triggers WHERE metric_key IN ('plain_article_coverage_pct', 'plain_article_hard_violations', 'plain_article_failed_final'); DELETE FROM metric_registry WHERE metric IN ('plain_article_coverage_pct', 'plain_article_hard_violations', 'plain_article_failed_final') AND last_value IS NULL
-- spof-review: no new cron, binding or credential; qnfo-gateway's existing hourly cron gains a step and calls the public Wikipedia API (simple.wikipedia.org, en.wikipedia.org) for link checks, the one new external host; its failure leaves an article without links and never blocks the article. Rows only in this file.
-- PLAIN-ARTICLE-1 (2026-10-26, charter pillar reach; qnfo-gateway 3.44.0). Owner directive 2026-10-26: for each and every paper the Quick Read rewrites the paper entirely in plain, simple language without jargon,
-- complex numeric or mathematical expressions, or domain-specific terminology; a brief plain-language summary links to it and encourages readers to click through to a deeper non-technical version (like Simple English
-- Wikipedia), with links to external resources in plain language. Before: the Quick Read was an extractive digest (quoted sentences, figures, a section map; QUICK-READ-DIGEST-1, no model by design) under a six-sentence
-- summary box of which 348 of 704 read above grade 9 (PLAIN-STANDARD-1). Now: a stored plain-language article per paper, built by the hourly cron (kimi-k2.6 writer, deterministic gate, gpt-oss-120b verifier, one repair),
-- shown above the folded digest, linked from the paper page's box, with Wikipedia links checked against the API. This file registers what the change adds: three published metrics with triggers (METRIC-CLOSED-LOOP-1), the
-- failure modes with detectors, the gate as a control with the probe of its alternate (CONTROL-PROBE-AT-BIRTH-1, agent_issues 1000483), the measures this change and ASK-PLAIN-1 name for the quality ledger
-- (OUTPUT-QUALITY-LEDGER-1; the reader-outcome measure is a stated gap, see docs/PAPER-AUTHORING-GUIDELINES.md), and the decision.

INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, baseline, target, owner, disposition_actor, refresh_cadence, warning_band, kill_band, state, refresh_class) VALUES
 ('plain_article_coverage_pct', 'reach', 'quality', 'share of published papers with a current plain-language article (status ok, version and text length equal the paper''s) after a 72-hour burn-in of the first backfill; published empty before that', 'living-paper.plain_article, published by qnfo-gateway articlePublishMetrics into analytics_dash_meta; GET https://papers.qnfo.org/_audit/quick-read (plain_articles)', 'new 2026-10-26', '>= 95', 'qnfo-gateway', 'qnfo-gateway hourly cron (PLAIN-ARTICLE-1): articleFill builds up to 15 papers a run, newest first, then stale, then failed', 'hourly', '< 95', '< 80', 'UNMEASURED', 'fast'),
 ('plain_article_hard_violations', 'reach', 'guard', 'count of stored plain-language articles above grade 12 or holding an equals sign, a dollar sign or a backslash; the gate never stores one, so the target is 0', 'living-paper.plain_article via analytics_dash_meta (qnfo-gateway articlePublishMetrics)', 'new 2026-10-26', '= 0', 'qnfo-gateway', 'qnfo-gateway hourly cron (PLAIN-ARTICLE-1)', 'hourly', '> 0', '> 0', 'UNMEASURED', 'fast'),
 ('plain_article_failed_final', 'reach', 'guard', 'count of papers whose plain-language article failed the gate on three attempts six hours apart and is left on the digest', 'living-paper.plain_article via analytics_dash_meta (qnfo-gateway articlePublishMetrics)', 'new 2026-10-26', '<= 35 (5% of the corpus)', 'qnfo-gateway', 'qnfo-gateway hourly cron (PLAIN-ARTICLE-1)', 'hourly', '> 35', '> 70', 'UNMEASURED', 'fast');

INSERT OR IGNORE INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT v.metric_key, v.title, 'meta', v.operator, v.threshold, v.priority, v.action || ' Definition of done: the metric is back inside its target in analytics_dash_meta at the next hourly cron; the issue closes on its probe.', 'qnfo-gateway', 'agent_issues', 24, 1, 'PLAIN-ARTICLE-1 2026-10-26'
FROM (SELECT 'plain_article_coverage_pct' AS metric_key, 'Quick Read: fewer than 90% of papers have a plain-language article' AS title, 'lt' AS operator, 90 AS threshold, 6 AS priority, 'Pillar reach. The hourly cron (qnfo-gateway articleFill) builds up to 15 papers a run, newest first. Read GET https://papers.qnfo.org/_audit/quick-read (plain_articles: current, failedFinal, meanGrade) and the plain_article.note column of failed rows (living-paper) for the pattern: a writer that returns nothing, a hard rule that the repair does not clear, or a grade above 12. If the writer or the verifier is the cause, the levers are ARTICLE_WRITER, ARTICLE_VERIFIER and the prompt in articlePrompt (qnfo-gateway/worker.js).' AS action
      UNION ALL SELECT 'plain_article_hard_violations', 'Quick Read: a stored plain-language article breaks a hard rule', 'gt', 0, 7, 'Pillar reach. The gate (articleProblems) refuses these before storing, so a nonzero count means a stored row predates a stricter rule or the gate has a hole. List the slugs: SELECT slug, grade FROM plain_article WHERE status = ''ok'' AND (grade > 12 OR instr(body, ''='') > 0 OR instr(body, ''$'') > 0) (living-paper), then rebuild them by bumping ARTICLE_RULES in qnfo-gateway/worker.js and fix the gate that let them through.'
      UNION ALL SELECT 'plain_article_failed_final', 'Quick Read: more than 35 papers have no plain-language article after three tries', 'gt', 35, 5, 'Pillar reach. Read plain_article.note for status failed and attempts 3 (living-paper): the papers are probably the hardest to put in plain words (dense mathematics) or the writer returns text the parser refuses. Fix the cause in articlePrompt or the gate, then reset attempts for those rows.') v
WHERE NOT EXISTS (SELECT 1 FROM analytics_metric_triggers x WHERE x.metric_key = v.metric_key AND x.enabled = 1);

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('quick-read-extract-not-plain', 'a paper''s Quick Read is a list of the paper''s own technical sentences, figures and section names, so a reader outside the field cannot use it; the plain-language box above it read above grade 9 on half the corpus',
  'QUICK-READ-DIGEST-1 made the Quick Read an extraction with no model, so that every line quotes the paper; that guarantee and the plain-language requirement (owner 2026-10-26) pull in opposite directions, and the box meant to cover it was six sentences made under a prompt that asked for key numbers',
  'PLAIN-ARTICLE-1 (qnfo-gateway 3.44.0): a stored plain-language rewrite of the whole paper (kimi-k2.6 writer, deterministic gate, gpt-oss-120b verifier, one repair) is shown first and the extractive digest below it, folded, with its own statement that no model wrote it; the paper page box links to the article',
  'code: the plain-language article block is in the gateway', 'fm-quick-read-extract-not-plain', '2026-10-26', NULL,
  'a reader without the paper''s field opens a Quick Read',
  'the page shows quoted sentences with symbols, figures and domain terms; nothing is written in everyday words',
  'every paper''s Quick Read (704 published papers)'),
 ('plain-article-coverage-stalls', 'the backfill or the hourly fill stops, so new papers have no plain-language article and the Quick Read shows the digest with a notice',
  'the fill is a step of the gateway''s hourly cron, bounded by ARTICLE_FILL_MAX and a six-minute budget; a failing writer, a verifier that never answers, a D1 error or a cron that does not run all leave the count of current articles where it was',
  'PLAIN-ARTICLE-1: plain_article_coverage_pct is published hourly (after a 72-hour burn-in) with a trigger at 90; failed rows retry after six hours, three times, and are counted in plain_article_failed_final',
  'plain_article_coverage_pct at or above 90 once the burn-in is over', 'fm-plain-article-coverage-stalls', '2026-10-26', NULL,
  'any day after the first backfill',
  'analytics_dash_meta plain_article_coverage_pct below 90, or empty past the burn-in',
  'new papers and revised papers, every day the fill is stalled');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, requires_container) VALUES
 ('fm-quick-read-extract-not-plain', NULL, 'PLAIN-ARTICLE-1', 'failure-mode detector: the gateway carries the plain-language article block',
  '{"paths": ["qnfo-gateway/worker.js"], "contains": "PLAIN-ARTICLE-1:BEGIN"}', 'code-read', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', 45000, 5, 0),
 ('fm-plain-article-coverage-stalls', NULL, 'PLAIN-ARTICLE-1', 'failure-mode detector: plain_article_coverage_pct is at or above 90 once the 72-hour burn-in is over (pending while it is empty)',
  'SELECT ''ok'' AS expected, CASE WHEN (SELECT value FROM analytics_dash_meta WHERE key = ''plain_article_coverage_pct'') IS NULL OR (SELECT value FROM analytics_dash_meta WHERE key = ''plain_article_coverage_pct'') = '''' THEN ''pending: plain_article_coverage_pct is not published yet (the first 72 hours of the backfill are a burn-in)'' WHEN CAST((SELECT value FROM analytics_dash_meta WHERE key = ''plain_article_coverage_pct'') AS REAL) >= 90 THEN ''ok'' ELSE ''fail: plain_article_coverage_pct '' || (SELECT value FROM analytics_dash_meta WHERE key = ''plain_article_coverage_pct'') || '' is under 90'' END AS observed',
  'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', 45000, 5, 0);

INSERT OR IGNORE INTO output_quality_measures (metric, surface, role, polarity, tol_rel, tol_abs, judged_by, caveat) VALUES
 ('plain_article_coverage_pct', 'papers', 'proxy', 1, 0.02, 1, 'a count: published papers with a current plain-language article over published papers', 'coverage is not quality: an article can pass every rule and still be wrong or dull. The reader outcome (how many readers who open the paper page''s plain-language box go on to the article and how many then stay) is not measured yet; it needs path-level human page views, see the gap noted in docs/PAPER-AUTHORING-GUIDELINES.md'),
 ('ask_plain_share_7d', 'ask', 'proxy', 1, 0.1, 0.05, 'a rule on the opening of an answer (ASK-PLAIN-1): six or more words copied from the wording asked about, sentences over 30 words on average, a fifth of the words with nine or more letters', 'a proxy for plain language, not for being right; the visitors'' rating (ask_helpful_rate_30d, 4 ratings in 30 days on 2026-10-26) is the outcome and is too thin to read');

INSERT OR IGNORE INTO control_registry (control, location, kind, guards_against, critical_path, disposition, disposition_state, alternate_path, alternate_tested_at, evidence, issue_id)
VALUES ('plain-article-gate', 'qnfo-gateway worker.js articleProblems and articleBuild: an article is stored only when no hard rule is broken after at most one repair', 'gate',
  'a plain-language article that still holds mathematics, symbols, Greek-letter names, links, a reading grade above 12 or text that is too short reaching a reader as "plain language" (PLAIN-ARTICLE-1)', 0, 'keep', 'applied',
  'the gate withholds only the article: the paper keeps its Quick Read digest and its short plain-language box, and a failed row is retried three times six hours apart; plain_article_hard_violations (published hourly, target 0) is the read-only check that nothing above the line was stored',
  NULL, 'qnfo-gateway/plain-article.test.mjs: the gate refuses each hard rule and passes a plain article; the build repairs once, never stores a failing article, and fails open when only the verifier is silent', NULL);

INSERT OR IGNORE INTO control_alternate_probes (control, probe_sql, window_note, enabled) VALUES
 ('plain-article-gate',
  'SELECT ''ok'' AS expected, CASE WHEN (SELECT value FROM analytics_dash_meta WHERE key = ''plain_article_hard_violations'') IS NULL THEN ''ok'' WHEN CAST((SELECT value FROM analytics_dash_meta WHERE key = ''plain_article_hard_violations'') AS INTEGER) > 0 THEN ''fail: '' || (SELECT value FROM analytics_dash_meta WHERE key = ''plain_article_hard_violations'') || '' stored plain-language article(s) break a hard rule'' ELSE ''ok'' END AS observed',
  'the value of the last hourly cron; before the first hourly run after the deploy the key does not exist and nothing has been stored, so the probe reads ok', 1);

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested) VALUES
  ('claude-code-plain-article-20261026', 'a reader outside a paper''s field is served by a plain rewrite of the whole paper, not by a list of its technical sentences, and a model can write it if a rule set and a second model of another family check it',
   'PLAIN-ARTICLE-1 (qnfo-gateway 3.44.0): a stored plain-language article per paper built by the hourly cron (kimi-k2.6, deterministic gate, gpt-oss-120b verifier, one repair, Simple English Wikipedia links checked against the API), shown above the folded digest, linked from the paper page box and returned by the API',
   'owner directive 2026-10-26; living-paper audit 2026-10-26 (PLAIN-STANDARD-1): 704 summaries, 348 above grade 9, 224 above grade 12; prototype runs against Workers AI 2026-10-26 on the hardest corpus type (anyon condensation with formulas): llama-3.3-70b 323 vague words at grade 8.1, gpt-oss-120b grade 11.5 with 14 symbols, kimi-k2.6 grade 7 to 8 with the paper''s content intact, 388 neurons; verifier 55 neurons; a repair 195 neurons; Simple English Wikipedia API returns the page or missing for each topic',
   'applies with the canonical deploy of qnfo-gateway 3.44.0; the backfill runs 15 papers an hour', 'every paper''s Quick Read and the paper page''s plain-language box; Workers AI spend of roughly 1000 to 2000 neurons per paper, about 704 papers once; one new external host (Wikipedia API) called only for link checks', 'revert qnfo-gateway to 3.43.4 through the canonical path; the plain_article rows stay and are ignored',
   'every paper has a plain-language version without jargon or mathematics, and the Quick Read leads with it',
   'plain_article_coverage_pct reaches 90 within about three days of the deploy; plain_article_hard_violations stays 0; the mean grade of stored articles is at most 9', 'every reader of papers.qnfo.org who is not an expert in the paper''s field', 'offline suite qnfo-gateway/plain-article.test.mjs (73 checks) and the existing gateway suites; prototype runs on live Workers AI; first live runs read from living-paper plain_article after the deploy');
